@startuml

class SensorController {
}

class Apartment {
  + address : string
  + emailAddress : string
}

class Inhabitant {
  + username : string
  + password : string
}

class Room {
  + description : string
}

class Sensor {
  + vendorId : string
  + description : string
  + unit : Unit
  + threshold : float
}

abstract class SensorType {}

class TemperatureSensor extends SensorType {
  + min : float
  + max : float
}

class PowerSensor extends SensorType {
  + counterReading : float
}

class MeasuredValue {
  + timestamp : datetime
  + value : float
}

class EMonitor {}

enum Unit {
  CELSIUS
  WATT
}

SensorController "1" -- "*" Apartment : manages
SensorController "1" -- "*" MeasuredValue : stores
Apartment "1" *-- "2..*" Room : consists of
Room "1" *-- "*" Sensor : contains
Sensor "1" -- "*" MeasuredValue : has
Sensor "1" -- "0..1" SensorType : is a
Inhabitant "*" -- "1" Apartment : lives in
Inhabitant "0..1" -- "*" Sensor : configures
EMonitor "1" -- "*" Sensor : checks thresholds
EMonitor "1" -- "1" SensorController : sends alerts to

@enduml

